// Technology pack: a backend built on the Cloudflare Workers runtime and its
// bindings — D1, R2, Vectorize, Workflows, Workers AI, Containers — driven
// through Wrangler. The platform's own limits and deploy-window hazards, and
// the binding boundary that forces everything else into plain, fake-tested
// modules.
//
// Fingerprint: a wrangler config (toml, json, or jsonc) at the repo root or
// one directory down (a monorepo's backend/ or worker/ dir), but never
// deeper, so a stray one in a nested fixture or example tree can't trip
// detection.
const MARKERS = ['wrangler.toml', 'wrangler.json', 'wrangler.jsonc'];
const hasMarkerNearRoot = (ctx) =>
  ctx.tracked.some((f) => {
    const parts = f.split('/');
    return MARKERS.includes(parts[parts.length - 1]) && parts.length <= 2;
  });

export default {
  version: '60906.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'the Cloudflare Workers platform: Wrangler, D1, R2, Vectorize, Workflows, Workers AI and Containers',
    excludes: 'shipping a static site with no Worker — static-website; a different serverless vendor — aws-sam; generic Node conventions — node',
  },
  marker: 'a wrangler.toml/.json/.jsonc config (at the repo root or one directory down)',
  detect: hasMarkerNearRoot,
};
===TOOLTIP
import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';

// WHY. The site's footer names the released version in a `title` tooltip, so a
// visitor can say which build they are looking at. That number is a copy of
// `package.json`'s version — the single source of truth the release bumps — and
// a copy that drifts is worse than no number at all: it names a build that is
// not the one being served, and nothing about the page looks wrong.
//
// The copy is generated, not hand-maintained: `scripts/bump-version.mjs` writes
// the version into `package.json` and stamps it into every page carrying the
// footer, in the same run. This rule is that generator's drift guard — it fires
// when a page's stamp disagrees with `package.json`, which is what a hand-edit,
// a half-applied release, or a page added without the stamp all look like.
//
// SCOPE. Every tracked `site/**.html` that carries the footer copyright element
// (`class="copyright"`). A page without that element has no claim to check; a
// page with it must carry a stamp, and the stamp must match.

const PAGE = /^site\/.*\.html$/;
const COPYRIGHT = /class="copyright"/;

// The stamp as authored: `title="version 1.0821.34"` on the copyright element.
// Exported so the generator and the fixture spell it one way.
export const STAMP = /title="version ([^"]*)"/;

const rule = {
  id: 'claudinite-website/site-version-tooltip',
  severity: 'blocking',
  description: "A site page's footer version tooltip must carry package.json's version",
  doc: '.claudinite/local/packs/claudinite-website/RULES.md',
  why: 'the tooltip is the only place a visitor can read which build they are on, and a stale copy names a build that was never served',

  run(ctx) {
    const pkg = ctx.read('package.json');
    if (pkg === null) return [];
    let version;
    try { version = JSON.parse(pkg).version; } catch { return []; }
    if (!version) return [];

    const out = [];
    const pages = [...new Set([...ctx.tracked, ...(ctx.files || [])])].filter((f) => PAGE.test(f));

    for (const page of pages) {
      const text = ctx.read(page);
      if (text === null || !COPYRIGHT.test(text)) continue;

      const lines = text.split('\n');
      const at = lines.findIndex((l) => COPYRIGHT.test(l));
      const stamped = STAMP.exec(lines[at] ?? '')?.[1];

      if (stamped === version) continue;
      out.push(finding(rule, {
        file: page,
        line: at + 1,
        what: stamped === undefined
          ? 'the footer copyright carries no version tooltip'
          : `the footer names version ${stamped}, but package.json says ${version}`,
        fix: 'run `npm run bump-version` — it writes package.json and stamps every page from it; never hand-edit either side',
      }));
    }

    return out;
  },
};

export default rule;
===VERSIONS
# Version history

Records for `packs/product-wiki/pack.mjs`'s `version` field, one row per version, newest first.
A version is cut on `main` after its changes land, so a row names the pull requests that
landed between the previous version and this one; the weekly history task writes the rows
a version is missing and leaves every row that already stands.

| Version | Date | What changed |
|---|---|---|
| 60905.1 | 2026-09-05 | Task declarations name what the run does to pull requests in the four-value `expected_outcome` vocabulary (#1695): `pr` became `fresh_pr` and `none` became `no_code_changes`, the same behaviour under the word that now sits beside `amend_existing_or_create_new_pr` and `supersede_existing_pr` — except that `wiki-growth` declares `amend_existing_or_create_new_pr` (owner, 2026-09-04): a round joins its pending review, so the `no-open-pr-touching:product-wiki/` precondition that existed to prevent a stacked round retires, and its `task.md` delivers on the branch and pull request the item names. |
| 60904.1 | 2026-09-04 | Absorb barriers into basics, and stop it interviewing on adoption (#1684) |
| 60903.2 | 2026-09-03 | The page-editing rules move out of `RULES.md` into the `writing-wiki-pages` skill, forced for `product-wiki/**` by `force-load-on-file-edits-paths` (#1648); the prose keeps the two rules for sessions that only read the wiki. |
| 60903.1 | 2026-09-02 | Task declarations converted to `task.json`; the declaration's comments moved into each task's README (#1633). |
| 60902.2 | 2026-09-02 | `RULES.md` drops the descriptive framing the pack README already carries — the file carries rules only. |
| 60902.1 | 2026-09-02 | `wiki-growth` converts to `preconditions: ['repo-active', 'no-open-pr-touching:product-wiki/']`. The pending-round gate is unchanged in substance (an open PR whose paths could not be read still counts as pending); what is new is that the pass now sleeps on a repo nobody works in, and resumes on the first active window (#1578). |
| 60830.3 | 2026-08-30 | `wiki-growth` authorizes `under:product-wiki/ && doc-changes` instead of the repo-wide `doc-changes`, so the round may land Markdown inside the tree it already anchors its precondition on, and a doc elsewhere or a non-doc file inside the wiki parks it for review (#1473). |
| 60830.2 | 2026-08-30 | `wiki-growth` declares `automerge: ['doc-changes']` — the wiki is Markdown pages, and anything else in a round's diff parks it for review (#1459). |
| 60830.1 | 2026-08-30 | Bundles the `explore-link` skill — the owner-given-source growth lane (#1421). |
| 60824.1 | 2026-08-24 | Prose names the scheduler at its new home in the `claudinite-tasks` pack (#1317). |
| 60823.3 | 2026-08-23 | `wiki-growth` gates on an open PR's pending `product-wiki/` paths instead of a `product-wiki-growth` label. |

