cat > packs/cloudflare-site/test/tasks/site-release/preconditions.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { terms, RELEASE_TASK_ID } from '../../../tasks/site-release/preconditions.mjs';

const gate = terms['unreleased-commits'];
const commits = (...list) => ({ commits: { list, count: list.length } });
// Newest first, the order the collector preserves.
const work = (sha) => ({ sha, task: null });
const release = (sha) => ({ sha, task: RELEASE_TASK_ID });

test('runs when work landed above the last release', () => {
  const verdict = gate.holds(commits(work('aaa1111'), release('bbb2222'), work('ccc3333')));
  assert.equal(verdict.holds, true);
  assert.match(verdict.reason, /1 commit/);
  assert.match(verdict.context[0], /aaa1111/);
  // The commit below the water mark is already out; naming it would tell the reader
  // this release carries work it does not.
  assert.doesNotMatch(verdict.context[0], /ccc3333/);
});

// The loop the gate exists to stop: the release's own bump commit keeps the window
// non-empty, so a membership test would re-release the same bytes every night.
test('declines when the newest commit is the release itself', () => {
  const verdict = gate.holds(commits(release('bbb2222'), work('ccc3333')));
  assert.equal(verdict.holds, false);
  assert.match(verdict.reason, /the last release itself/);
});

// The same night's second pickup — a re-queue, or a force beside the anchor — must
// reach the same verdict, or a forced release doubles up.
test('a second evaluation after a release still declines', () => {
  const after = commits(release('bbb2222'), work('ccc3333'));
  assert.equal(gate.holds(after).holds, false);
  assert.equal(gate.holds(after).holds, false);
});

test('runs when the window holds work and no release at all', () => {
  assert.equal(gate.holds(commits(work('aaa1111'))).holds, true);
});

test('declines on a branch that did not move', () => {
  const verdict = gate.holds(commits());
  assert.equal(verdict.holds, false);
  assert.match(verdict.reason, /no commit landed/);
});

// A run of releases with nothing between them is the shape a re-queued park leaves.
test('consecutive releases at the top count as nothing to release', () => {
  assert.equal(gate.holds(commits(release('bbb2222'), release('bbb1111'), work('ccc3333'))).holds, false);
});

// The gate reads one signal and must declare it, or the collector never gathers what
// `holds` reaches for and every night reads an empty list as "nothing to release".
test('the signal the gate reads is the signal it declares', () => {
  assert.deepEqual(gate.signals, ['commits']);
  assert.equal(gate.holds({}).holds, false);
});

// The worker stamps its release commits with the id the queue hands it —
// `<pack>/<task>`, derived from the two directory names — and the gate recognises a
// release commit by comparing against this literal. A rename of either directory
// silently stops the gate seeing the release's own commits, which releases the same
// bytes every night forever.
test("the gate's task id is the one the directories give the queue", () => {
  assert.equal(RELEASE_TASK_ID, 'cloudflare-site/site-release');
});
EOF
cat > packs/cloudflare-site/test/tasks/site-release/preflight.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { judgeHostname, preflight, probeHostname } from '../../../tasks/site-release/preflight.mjs';

const answers = (records) => ({
  ok: true,
  json: async () => ({ Answer: records }),
});

// A resolver that answers per query type, so a case states what public DNS returns.
const resolver = (byType) => async (url) => {
  const type = new URL(url).searchParams.get('type');
  return answers(byType[type] ?? []);
};

test('an inherited CNAME on a claimed hostname is what blocks the attach', () => {
  const verdict = judgeHostname('www.example.com', { cname: ['owner.github.io'], a: [] });
  assert.match(verdict.what, /CNAME to owner\.github\.io/);
  assert.match(verdict.fix, /delete the www\.example\.com CNAME record/);
});

test("the old host's apex addresses are named as still-serving, not as blocking", () => {
  const verdict = judgeHostname('example.com', { cname: [], a: ['185.199.110.153'] });
  assert.match(verdict.what, /still resolves to GitHub Pages \(185\.199\.110\.153\)/);
  assert.match(verdict.fix, /visitors keep reaching the old host/);
});

// The steady state, and the one the release must not park on: a hostname Cloudflare
// already serves answers with its own addresses.
test('a hostname Cloudflare already serves is not a finding', () => {
  assert.equal(judgeHostname('example.com', { cname: [], a: ['104.21.0.1', '172.67.0.1'] }), null);
  assert.equal(judgeHostname('example.com', { cname: [], a: [] }), null);
});

test('a flattened CNAME answer is read as the address record it is', async () => {
  const answersFor = await probeHostname('example.com', resolver({
    CNAME: [{ type: 1, data: '104.21.0.1' }],
    A: [{ type: 1, data: '104.21.0.1' }],
  }));
  assert.deepEqual(answersFor, { cname: [], a: ['104.21.0.1', '104.21.0.1'] });
  assert.equal(judgeHostname('example.com', answersFor), null);
});

// An unreachable resolver is a statement about the probe, never a verdict on the
// hostname: a release that parked on it would stop for the network being down.
test('an unreachable resolver is inconclusive rather than a block', async () => {
  const dead = async () => { throw new Error('ENOTFOUND'); };
  assert.equal(await probeHostname('example.com', dead), null);
  const { blocked, unprobed } = await preflight(['example.com'], { fetchImpl: dead });
  assert.deepEqual(blocked, []);
  assert.deepEqual(unprobed, ['example.com']);
});

test('a resolver error status is inconclusive too', async () => {
  const refused = async () => ({ ok: false, status: 429, json: async () => ({}) });
  const { blocked, unprobed } = await preflight(['example.com'], { fetchImpl: refused });
  assert.deepEqual(blocked, []);
  assert.deepEqual(unprobed, ['example.com']);
});

test('every claimed hostname is judged, not just the first', async () => {
  const byHost = {
    'example.com': { A: [{ type: 1, data: '185.199.108.153' }] },
    'www.example.com': { CNAME: [{ type: 5, data: 'owner.github.io.' }] },
  };
  const fetchImpl = async (url) => {
    const u = new URL(url);
    return resolver(byHost[u.searchParams.get('name')])(url);
  };
  const { blocked } = await preflight(['example.com', 'www.example.com'], { fetchImpl });
  assert.equal(blocked.length, 2);
  assert.match(blocked[0].what, /example\.com still resolves/);
  assert.match(blocked[1].what, /CNAME to owner\.github\.io/);
});
