// Fixtures for the two release rules this repo still owns. The Cloudflare deployment
// itself — the upload boundary, the version stamp, the beacon token and the single
// path to production — is the cloudflare-site pack's, tested in the canon. What is
// left here is what only this site can say: its privacy disclosure, and its own
// README's description of how it reaches production.
//
// The bar: a violating input must produce a finding, a clean one must produce none —
// proved on the compiled declarations against synthetic contexts, never on the live
// repo, whose content is exactly what these rules are there to keep true.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadDeclaredChecks } from '../../../shared/engine/checks/helpers/pattern-rules.mjs';

const rules = loadDeclaredChecks(dirname(fileURLToPath(import.meta.url)));
const ruleFor = (id) => {
  const rule = rules.find((r) => r.id === `claudinite-website/${id}`);
  assert.ok(rule, `no declared check named claudinite-website/${id}`);
  return rule;
};

const ctxWith = (files) => ({
  mode: 'all',
  tracked: Object.keys(files),
  files: Object.keys(files),
  allFiles: Object.keys(files),
  read: (p) => (p in files ? files[p] : null),
  exists: (p) => p in files,
});

const wrangler = (over = {}) => JSON.stringify({
  name: 'claudinite-website',
  compatibility_date: '2026-09-08',
  assets: { directory: './site' },
  ...over,
});

// --- no-server-behind-the-page ----------------------------------------------

test('fires when a Worker script is added behind the static site', () => {
  const rule = ruleFor('no-server-behind-the-page');
  const found = rule.run(ctxWith({ 'wrangler.json': wrangler({ main: 'src/index.js' }) }));
  assert.equal(found.length, 1);
  assert.match(found[0].what, /Worker script/);
});

test('stays quiet on the static-assets-only config the site actually ships', () => {
